#include <stdio.h>
int factorial(int n)
{
    if( n <= 1 )  return 1;
    else return n * factorial(n-1);
}
int main(void)
{
    int r = factorial({{n}});
    printf("%d\n", r);
    return 0;
}

#include <stdio.h>
int factorial(int n)
{
    /* 순환을 멈추는 부분을 지웠다 */
    return n * factorial(n-1);
}
int main(void)
{
    int r = factorial({{n}});
    printf("%d\n", r);
    return 0;
}
